package com.axiom.api.controller;import com.axiom.application.testreport.TestReportIngestionService;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class TestReportController {private final TestReportIngestionService service;private final JdbcTemplate jdbc;public TestReportController(TestReportIngestionService s,JdbcTemplate j){service=s;jdbc=j;}@PostMapping(value="/pipeline-runs/{id}/test-reports",consumes={"application/xml","text/xml"})@ResponseStatus(HttpStatus.CREATED)public Object ingest(@PathVariable UUID id,@RequestParam String sourceName,@RequestParam(required=false) String frameworkHint,@RequestBody byte[] xml){return service.ingest(id,sourceName,xml,frameworkHint);}@GetMapping("/pipeline-runs/{id}/tests")public Object tests(@PathVariable UUID id){return jdbc.queryForList("select total_tests,passed,failed,errors,skipped from test_reports where pipeline_run_id=?",id);}@GetMapping("/pipeline-runs/{id}/tests/failures")public Object failures(@PathVariable UUID id){return jdbc.queryForList("select * from test_case_executions where pipeline_run_id=? and status in ('FAILED','ERROR')",id);}@GetMapping("/tests/{stable}/executions")public Object history(@PathVariable String stable){return jdbc.queryForList("select * from test_case_executions where stable_test_id=?",stable);}}
